struct stringx {
    char data[8];
    stringx();
    ~stringx();
    stringx &operator=(const stringx &);
};

class timer_widget {
public:
    struct timer_func {
        float time;
        stringx function;

        timer_func(const timer_func &other)
          : time(other.time), function()
        {
            function = other.function;
        }

        timer_func &operator=(const timer_func &other)
        {
            time = other.time;
            function = other.function;
            return *this;
        }
    };
};

template<class T>
struct my_allocator : public allocator<T> {
};

template class vector<
    timer_widget::timer_func,
    my_allocator<timer_widget::timer_func>
>;
